const sessionId = typeof $json.sessionId === 'string' ? $json.sessionId.trim() : '';
const requestId = typeof $json.requestId === 'string' ? $json.requestId.trim() : '';
const rawDomain = typeof $json.domain === 'string' ? $json.domain.trim() : '';
const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
let domain = '';
let error = null;
if (!uuidPattern.test(sessionId) || !uuidPattern.test(requestId)) {
  error = { code: 'INVALID_SESSION', message: 'The memory request needs a valid conversation and request ID.' };
}
if (!error && rawDomain) {
  // n8n Code nodes run in a vm sandbox that has no URL global, so the host is
  // parsed with string operations only. The URL constructor throws a
  // ReferenceError here, which a catch block reports as an invalid domain.
  let host = rawDomain.toLowerCase();
  const schemeMatch = host.match(/^([a-z][a-z0-9+.-]*):\/\//);
  if (schemeMatch) {
    host = ['http', 'https'].includes(schemeMatch[1]) ? host.slice(schemeMatch[0].length) : '';
  }
  host = host.split('/')[0].split('?')[0].split('#')[0];
  const portMatch = host.match(/^(.*):([0-9]*)$/);
  if (portMatch) {
    host = portMatch[1];
  }
  host = host.replace(/\.$/, '').replace(/^www\./, '');
  const labels = host.split('.');
  if (host === '' || host.length > 253 || host.includes('@') || host.includes('[') || host.includes(']') || host.includes(' ') || labels.length < 2 || labels.some((label) => !/^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(label))) {
    error = { code: 'INVALID_DOMAIN', message: 'Use a complete saved business domain such as example.com.' };
  } else {
    domain = host;
  }
}
const proposedInput = { sessionId, requestId, domain };
return { json: { valid: error === null, ...proposedInput, proposedInput, ...(error ? { response: { ok: false, error } } : {}) } };

const input = $('Validate Memory Input').first().json;
const memories = Array.isArray($json.memories) ? $json.memories : null;
const response = memories
  ? { ok: true, domain: input.domain || null, count: memories.length, memories, message: memories.length ? 'Saved business research loaded from local memory.' : 'No saved business research was found for that domain.' }
  : { ok: false, error: { code: 'BUSINESS_MEMORY_UNAVAILABLE', message: String($json.error?.message ?? 'Saved business research is not available right now.') } };
return { json: { ...input, response } };

const input = $('Validate Memory Input').first().json;
const response = $json.response ?? { ok: false, error: { code: 'BUSINESS_MEMORY_UNAVAILABLE', message: 'Saved business research is not available right now.' } };
return { json: { occurredAt: new Date().toISOString(), sessionId: input.sessionId, requestId: input.requestId, toolName: 'get_business_memory', proposedInput: JSON.stringify(input.proposedInput ?? {}), result: JSON.stringify(response), error: response.ok === false ? String(response.error?.message ?? 'Tool failed') : '', response } };

const prepared = $('Prepare Audit').item.json;
const response = { ...prepared.response };
if (!Number.isInteger($json.id)) response.auditWarning = 'The tool result could not be written to the local audit table.';
return { json: response };
